// v0.8: grammar topics that the map did not cover on their own (every use of
// "would", used to / be used to / get used to, just-already-yet, be able to,
// subjunctive, make/do, get, -ever words, like/as, imperatives, So do I,
// indefinite pronouns, word formation, movement prepositions). Each lesson has
// an Özet and five practice items, like the drills of the other Özet lessons.
// Original, AI-assisted teaching text. review: unreviewed

const q = (question, options, answer, explanation) => ({ question, options, answer, explanation });
const m = (prompt, options, answer, why) => ({ stage: "recognition", type: "mcq", prompt, options, answer, why });
const g = (prompt, answer, why, accept = []) => ({ stage: "transformation", type: "gap", prompt, answer, accept, why });
const f = (source, answer, why, accept = []) => ({ stage: "transformation", type: "rewrite", prompt: "Correct the mistake and write the whole sentence.", source, answer, accept, why });
const ozet = (summary, explanation, examples, examUse, quiz) => ({ summary, explanation, examples: examples.map(([en, tr]) => ({ en, tr })), examUse, quiz });

